```json
{
  "root_causes": [
    {
      "service": "payment",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'normal' period, service_name, span_name, count(*) n FROM normal_traces WHERE service_name='payment' GROUP BY ALL UNION ALL SELECT 'abnormal', service_name, span_name, count(*) FROM abnormal_traces WHERE service_name='payment' GROUP BY ALL",
          "claim": "Payment produced 19 Charge spans in the normal period and zero spans of any kind in the abnormal period."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'normal' period, service_name, span_name, count(*) n FROM normal_traces WHERE service_name='checkout' AND span_name IN ('oteldemo.PaymentService/Charge','oteldemo.CheckoutService/PlaceOrder') GROUP BY ALL UNION ALL SELECT 'abnormal', service_name, span_name, count(*) FROM abnormal_traces WHERE service_name='checkout' AND span_name IN ('oteldemo.PaymentService/Charge','oteldemo.CheckoutService/PlaceOrder') GROUP BY ALL",
          "claim": "Checkout's PlaceOrder and its Charge calls, 19 each in normal, are entirely absent in the abnormal period."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, metric, count(*) n, round(avg(value),3) av FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'payment%' AND metric IN ('container.cpu.usage','k8s.container.restarts') GROUP BY ALL",
          "claim": "Payment pod metrics show flat CPU and zero restarts while its request spans disappear, so the pod stopped serving requests without restarting."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "payment",
      "to": "checkout",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, quantile_cont(duration,0.5)/1e6 p50_ms, max(duration)/1e6 max_ms FROM abnormal_traces WHERE service_name='checkout' AND span_name IN ('prepareOrderItemsAndShippingQuoteFromCart','HTTP POST') GROUP BY ALL",
          "claim": "Checkout requests stop after quote preparation (about 10 ms) and never reach payment Charge, leaving the PlaceOrder unfinished."
        }
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, min(duration)/1e6 min_ms, max(duration)/1e6 max_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='POST' AND duration>14e9 GROUP BY ALL",
          "claim": "19 frontend POST requests, the checkout calls, hang for about 15 seconds instead of finishing in about 3 ms."
        }
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code st, attr_status_code, count(*) n, quantile_cont(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE service_name='frontend-proxy' AND span_name IN ('ingress','router frontend egress') AND attr_http_response_status_code IN (0,504) GROUP BY ALL",
          "claim": "Frontend-proxy returns 504 after about 15 s on the ingress path, because its frontend egress times out at the proxy."
        }
      ]
    }
  ]
}
```

